[{"order":1,"type":"heading","text":"Polymorphism in PHP: Interfaces and Abstract Classes"},{"order":2,"type":"paragraph","text":"Polymorphism, meaning "many forms", is a fundamental concept in object-oriented programming (OOP). It allows objects of different classes to be treated as objects of a common type. In PHP, polymorphism is primarily achieved through interfaces and abstract classes."},{"order":3,"type":"subheading","text":"Interfaces"},{"order":4,"type":"paragraph","text":"An interface defines a contract that classes must adhere to. It specifies a set of methods that a class implementing the interface must implement. Interfaces cannot have properties, only method signatures. They provide a way to enforce a specific behavior across different classes."},{"order":5,"type":"code","text":"<?php
interface Logger {
    public function log(string $message);
}

class FileLogger implements Logger {
    private $filename;

    public function __construct(string $filename) {
        $this->filename = $filename;
    }

    public function log(string $message) {
        file_put_contents($this->filename, $message . "\n", FILE_APPEND);
    }
}

class DatabaseLogger implements Logger {
    private $connection;

    public function __construct(PDO $connection) {
        $this->connection = $connection;
    }

    public function log(string $message) {
        $stmt = $this->connection->prepare("INSERT INTO logs (message) VALUES (:message)");
        $stmt->execute(['message' => $message]);
    }
}

function processLog(Logger $logger, string $message) {
    $logger->log($message);
}

// Usage
$fileLogger = new FileLogger('application.log');
processLog($fileLogger, 'This is a file log message.');

$dbConnection = new PDO('mysql:host=localhost;dbname=mydb', 'user', 'password');
$databaseLogger = new DatabaseLogger($dbConnection);
processLog($databaseLogger, 'This is a database log message.');

?>"},{"order":6,"type":"paragraph","text":"In this example, the `Logger` interface defines a `log` method. Both `FileLogger` and `DatabaseLogger` implement this interface, providing their own specific implementations of the `log` method. The `processLog` function accepts any object that implements the `Logger` interface, demonstrating polymorphism."},{"order":7,"type":"subheading","text":"Abstract Classes"},{"order":8,"type":"paragraph","text":"An abstract class is a class that cannot be instantiated directly. It serves as a blueprint for other classes. Abstract classes can contain both abstract methods (methods without implementation) and concrete methods (methods with implementation). Subclasses must implement all abstract methods defined in the abstract class."},{"order":9,"type":"code","text":"<?php
abstract class AbstractNotifier {
    abstract public function send(string $message, string $recipient);

    public function formatMessage(string $message): string {
        return "[Important] " . $message;
    }
}

class EmailNotifier extends AbstractNotifier {
    public function send(string $message, string $recipient) {
        // Code to send email
        echo "Sending email to " . $recipient . ": " . $this->formatMessage($message) . "\n";
    }
}

class SMSNotifier extends AbstractNotifier {
    public function send(string $message, string $recipient) {
        // Code to send SMS
        echo "Sending SMS to " . $recipient . ": " . $this->formatMessage($message) . "\n";
    }
}

// Usage
$emailNotifier = new EmailNotifier();
$emailNotifier->send('Alert: System is down!', 'user@example.com');

$smsNotifier = new SMSNotifier();
$smsNotifier->send('Alert: System is down!', '+15551234567');

?>"},{"order":10,"type":"paragraph","text":"In this example, `AbstractNotifier` is an abstract class with an abstract method `send` and a concrete method `formatMessage`. `EmailNotifier` and `SMSNotifier` extend `AbstractNotifier` and provide their own implementations of the `send` method. This demonstrates polymorphism because both `EmailNotifier` and `SMSNotifier` can be treated as `AbstractNotifier` objects."},{"order":11,"type":"subheading","text":"Key Differences and When to Use Which"},{"order":12,"type":"bullet_point","text":"Interfaces define a contract; classes implementing the interface *must* implement all methods."},{"order":13,"type":"bullet_point","text":"Abstract classes can have both abstract and concrete methods, allowing for partial implementation."},{"order":14,"type":"bullet_point","text":"A class can implement multiple interfaces, but it can only inherit from one abstract class."},{"order":15,"type":"bullet_point","text":"Use interfaces when you want to define a role or capability that multiple unrelated classes can fulfill."},{"order":16,"type":"bullet_point","text":"Use abstract classes when you want to provide a common base class with some shared implementation and force subclasses to implement specific methods."},{"order":17,"type":"paragraph","text":"In summary, both interfaces and abstract classes are powerful tools for achieving polymorphism in PHP, allowing you to write more flexible and maintainable code."}]
